export type InformationType =
  | 'Fact'
  | 'AI Generated'
  | 'Derived'
  | 'Forecast'
  | 'Target'

interface MetadataLabelsProps {
  source: string
  informationType: InformationType
}

const descriptions: Record<InformationType, string> = {
  Fact: 'Deterministically calculated from observed data',
  'AI Generated': 'Content generated by an AI model',
  Derived: 'Calculated from existing analytical facts',
  Forecast: 'Predicted future value',
  Target: 'Defined performance objective',
}

export function MetadataLabels({
  source,
  informationType,
}: MetadataLabelsProps) {
  return (
    <div className="metadata-labels">
      <span
        className="metadata-source"
        title={`Data source: ${source}`}
      >
        {source}
      </span>

      <span
        className="metadata-type"
        data-type={informationType}
        title={descriptions[informationType]}
      >
        {informationType}
      </span>
    </div>
  )
}
